// Geography missions: stateful, non-quiz interactions. Existing saved question-based lessons remain supported.
const GP_TYPES={map:'Build a map',route:'Navigate a route',links:'Connect a network',timeline:'Reconstruct a timeline',sort:'Sort a field collection',redact:'Repair a report',compose:'Build an explanation',budget:'Pack and test a plan',allocate:'Negotiate resources',ice:'Run a glacier laboratory',river:'Run a river laboratory',profile:'Draw a landscape profile',chart:'Plot field data',deduce:'Investigate a mystery',layers:'Plan with map layers',survey:'Collect a field sample',build:'Draw a scaled blueprint',sculpt:'Sculpt a landscape'};
function gpIs(q){return typeof q?.geo?.kind==='string'&&q.geo.kind.startsWith('gp-');}
function gpAssert(ok,message){if(!ok)throw Error(message);}
function gpText(v,max=500){gpAssert(typeof v==='string'&&v.trim().length>0&&v.length<=max,'Mission text must be short and non-empty.');return v.trim();}
function gpNumber(v,min=0,max=100){gpAssert(Number.isInteger(v)&&v>=min&&v<=max,'Mission numbers are outside the supported range.');return v;}
function gpArray(v,min=1,max=12){gpAssert(Array.isArray(v)&&v.length>=min&&v.length<=max,'Check the number of entries in this mission.');return v;}
function gpFields(item){const raw=item.geo,kind=raw.kind.slice(3);gpAssert(Object.hasOwn(GP_TYPES,kind),'Choose a supported mission.');gpAssert(raw.task&&typeof raw.task==='object'&&!Array.isArray(raw.task),'Add the mission data in the editor.');gpAssert(JSON.stringify(raw.task).length<25000,'Keep mission data under 25 KB.');const t=JSON.parse(JSON.stringify(raw.task));t.brief=gpText(t.brief,1400);t.check=gpText(t.check||'Use the evidence to explain how your completed work meets the mission.',1000);
 if(['map','build'].includes(kind)){gpArray(t.targets,2,8).forEach(p=>{gpText(p.label,60);gpNumber(p.x,0,5);gpNumber(p.y,0,4);if(kind==='build'){gpNumber(p.w,1,6-p.x);gpNumber(p.h,1,5-p.y);}});gpAssert(new Set(t.targets.map(p=>p.label)).size===t.targets.length,'Map labels must be unique.');if(t.image)t.image=activityImage(t.image);}
 if(kind==='route'){gpArray(t.blocked,0,20).forEach(n=>gpNumber(n,0,29));gpArray(t.stops,0,6).forEach(n=>gpNumber(n,0,29));gpNumber(t.start,0,29);gpNumber(t.goal,0,29);gpNumber(t.limit,1,40);gpAssert(!t.blocked.includes(t.start)&&!t.blocked.includes(t.goal)&&t.stops.every(n=>!t.blocked.includes(n)),'A route cannot put its start, goal or required stop on a blocked square.');const queue=[[t.start,0,0]],seen=new Set();let possible=false;while(queue.length){const [at,cost,mask]=queue.shift(),key=at+':'+mask;if(seen.has(key)||cost>t.limit)continue;seen.add(key);if(at===t.goal&&mask===(1<<t.stops.length)-1){possible=true;break;}for(const next of gpNeighbours(at)){if(!t.blocked.includes(next))queue.push([next,cost+1,mask|(t.stops.includes(next)?1<<t.stops.indexOf(next):0)]);}}gpAssert(possible,'The route must be reachable within the move allowance, including every stop.');}
 if(['links','timeline','sort','compose','redact'].includes(kind)){gpArray(t.cards,3,10).forEach(c=>gpText(c.label,220));if(['sort','compose'].includes(kind)){gpArray(t.bins,2,4).forEach(x=>gpText(x,70));t.cards.forEach(c=>gpNumber(c.bin,0,t.bins.length-1));}if(kind==='links'){gpArray(t.edges,2,10).forEach(e=>{gpArray(e,2,2);e.forEach(n=>gpNumber(n,0,t.cards.length-1));gpAssert(e[0]!==e[1],'A link must connect different nodes.');});}if(kind==='timeline'){t.cards.forEach(c=>gpNumber(c.order,0,10000));gpAssert(new Set(t.cards.map(c=>c.order)).size===t.cards.length,'Timeline positions need unique order values.');}if(kind==='redact'){t.cards.forEach(c=>gpAssert(typeof c.keep==='boolean','Mark each report statement as supported or unsupported.'));gpAssert(t.cards.some(c=>c.keep)&&t.cards.some(c=>!c.keep),'Include supported statements and at least one unsupported statement.');}}
 if(kind==='budget'){gpNumber(t.budget,1,40);gpNumber(t.weight,1,40);gpArray(t.needs,2,4).forEach(n=>gpText(n,60));gpArray(t.items,4,8).forEach(p=>{gpText(p.label,80);gpNumber(p.cost,1,30);gpNumber(p.weight,0,20);gpNumber(p.cover,0,(1<<t.needs.length)-1);});let possible=false;for(let m=0;m<2**t.items.length;m++){let c=0,w=0,n=0;t.items.forEach((p,i)=>{if(m&(1<<i)){c+=p.cost;w+=p.weight;n|=p.cover;}});if(c<=t.budget&&w<=t.weight&&n===(1<<t.needs.length)-1)possible=true;}gpAssert(possible,'No packing plan meets this budget, weight and needs.');}
 if(kind==='allocate'){gpNumber(t.total,2,40);gpArray(t.users,3,5).forEach(p=>{gpText(p.label,60);gpNumber(p.min,0,20);gpNumber(p.max,p.min,30);});gpAssert(t.users.reduce((n,u)=>n+u.min,0)<=t.total,'Resource needs exceed the available supply.');}
 if(kind==='ice'){gpNumber(t.start,1,30);gpNumber(t.target,1,40);gpArray(t.weather,2,5).forEach(n=>gpNumber(n,0,6));gpNumber(t.snow,1,30);const need=t.target-t.start+t.weather.reduce((a,b)=>a+b,0);gpAssert(need>=0&&need<=t.snow,'The ice target is not reachable with this snowfall supply.');}
 if(kind==='river'){gpArray(t.sizes,3,6).forEach(n=>gpNumber(n,1,5));gpArray(t.targets,t.sizes.length,t.sizes.length).forEach(n=>gpNumber(n,0,2));gpArray(t.solution,3,3).forEach(n=>gpNumber(n,0,5));gpAssert(gpRiverLanding(t.sizes,t.solution).every((x,i)=>x===t.targets[i]),'River energy settings must be able to produce the target deposits.');}
 if(['profile','chart'].includes(kind)){gpArray(t.values,4,8).forEach(n=>gpNumber(n,0,10));gpArray(t.labels,t.values.length,t.values.length).forEach(n=>gpText(n,40));}
 if(kind==='deduce'){gpArray(t.suspects,4,6).forEach(c=>{gpText(c.label,70);gpArray(c.facts,3,3).forEach(x=>gpText(x,140));});gpNumber(t.target,0,t.suspects.length-1);gpArray(t.questions,3,3).forEach(x=>gpText(x,100));const facts=t.suspects[t.target].facts;gpAssert(t.suspects.every((c,i)=>i===t.target||c.facts.some((f,k)=>f!==facts[k])),'The clues must distinguish the mystery candidate.');}
 if(kind==='layers'){gpArray(t.layers,3,4).forEach(l=>{gpText(l.label,60);gpArray(l.cells,1,20).forEach(n=>gpNumber(n,0,29));});gpArray(t.valid,1,10).forEach(n=>gpNumber(n,0,29));gpText(t.rule,400);}
 if(kind==='survey'){gpArray(t.values,30,30).forEach(n=>gpNumber(n,0,20));gpNumber(t.samples,3,8);gpArray(t.zones,30,30).forEach(n=>gpNumber(n,0,2));}
 if(kind==='sculpt'){gpArray(t.rock,24,24).forEach(n=>gpNumber(n,0,3));gpArray(t.target,24,24).forEach(n=>gpNumber(n,0,3));gpText(t.process,100);}
 return {geo:{kind:raw.kind,source:String(raw.source||t.brief).slice(0,1800),task:t},answer:gpWorked(kind,t)};
}
function gpWorked(k,t){if(k==='map'||k==='build')return t.targets.map(p=>p.label+': column '+(p.x+1)+', row '+(p.y+1)+(k==='build'?', '+p.w+' × '+p.h+' squares':'')).join('; ');if(k==='timeline')return [...t.cards].sort((a,b)=>a.order-b.order).map(c=>c.label).join(' → ');if(k==='sort'||k==='compose')return t.cards.map(c=>c.label+' → '+t.bins[c.bin]).join('; ');if(k==='redact')return 'Supported: '+t.cards.filter(c=>c.keep).map(c=>c.label).join(' ');if(k==='links')return t.edges.map(([a,b])=>t.cards[a].label+' → '+t.cards[b].label).join('; ');if(k==='chart'||k==='profile')return t.labels.map((l,i)=>l+': '+t.values[i]).join('; ');if(k==='deduce')return t.suspects[t.target].label+' — '+t.suspects[t.target].facts.join('; ');return t.check;}
function gpNeighbours(n){return [n%6>0?n-1:-1,n%6<5?n+1:-1,n>=6?n-6:-1,n<24?n+6:-1].filter(x=>x>=0);}
function gpRiverLanding(sizes,energy){return sizes.map(size=>{const n=energy.findIndex(e=>e<size);return n<0?2:n;});}
function gpNew(q){const t=q.geo.task,k=q.geo.kind.slice(3);return {selected:null,placed:{},assigned:{},edges:[],order:[],removed:[],chosen:[],values:(t.users||t.values||[0,0,0]).map(()=>0),layers:[],site:null,path:k==='route'?[t.start]:[],asked:[],eliminated:[],samples:[],prediction:0,rock:[...(t.rock||[])],tool:'remove',year:0,ice:t.start||0,snowLeft:t.snow||0,snowNow:0,years:[],energy:[0,0,0],ran:false,tries:0,notice:'',studied:!t.memory,dimensions:{w:1,h:1},drawing:false};}
const gpOldFields=geoFields;geoFields=function(item){return gpIs(item)?gpFields(item):gpOldFields(item);};
const gpOldRound=geoRound;geoRound=function(l){gpOldRound(l);const q=game.items[l.index];if(gpIs(q)){l.gp=gpNew(q);l.gp.deck=shuffle(Array.from({length:q.geo.task.cards?.length||0},(_,i)=>i));}};
function gpButton(i,a,label,n='',extra='',disabled=false){return geoButton(i,'play-'+a,label,'data-value="'+n+'" '+extra,disabled);}
function gpGrid(s,contents,extra=''){return '<div class="gp-grid" '+extra+'>'+Array.from({length:30},(_,n)=>contents(n)).join('')+'</div>';}
function gpMotion(){return !document.body.classList.contains('still-games')&&!matchMedia('(prefers-reduced-motion: reduce)').matches;}
function gpTaskUI(i,q,l){const k=q.geo.kind.slice(3),t=q.geo.task,s=l.gp,B=(a,label,n='',extra='',disabled=false)=>gpButton(i,a,label,n,extra,disabled);let html='';
 if(k==='map'||k==='build'){
 if(t.memory&&!s.studied)return '<p class="gp-instruction">Study the positions. Hide the plan when you are ready to rebuild it.</p>'+gpGrid(s,n=>'<div class="gp-cell">'+t.targets.filter(p=>p.y*6+p.x===n).map(p=>'<b>'+esc(p.label)+'</b>').join('')+'</div>')+B('hide','Hide reference & rebuild');
 html='<div class="gp-palette">'+t.targets.map((p,n)=>B('token','<b>'+String.fromCharCode(65+n)+'</b> · '+esc(p.label),n,'class="gp-token" data-geo-drag="'+n+'" aria-pressed="'+(s.selected===n)+'"')).join('')+'</div>'+(k==='build'?'<div class="gp-inline"><b>Draw size: '+s.dimensions.w+' × '+s.dimensions.h+'</b>'+B('width','Width −',-1)+B('width','Width +',1)+B('height','Height −',-1)+B('height','Height +',1)+'</div>':'')+gpGrid(s,n=>{const cover=Object.entries(s.placed).find(([,v])=>n%6>=v.x&&n%6<v.x+(k==='build'?v.w:1)&&Math.floor(n/6)>=v.y&&Math.floor(n/6)<v.y+(k==='build'?v.h:1)),p=Object.entries(s.placed).filter(([,v])=>v.y*6+v.x===n);return B('cell','<small>'+String.fromCharCode(65+n%6)+(Math.floor(n/6)+1)+'</small>'+p.map(([key,v])=>'<strong>'+String.fromCharCode(65+Number(key))+(k==='build'?' · '+v.w+'×'+v.h:'')+'</strong>').join(''),n,'class="gp-cell" '+(cover?'style="background:'+['#f4d390','#b5ddeb','#ccddab','#e0c3e9','#ebc4ae'][Number(cover[0])%5]+'" ':'')+'data-gp-drop="'+n+'"');},t.image?'style="background-image:url('+t.image+');background-size:100% 100%"':'');
 }
 if(k==='route')html='<div class="gp-inline"><b>Route distance: '+Math.max(0,s.path.length-1)+' / '+t.limit+' km</b><span>📍 '+t.stops.filter(n=>s.path.includes(n)).length+' / '+t.stops.length+' supply stops</span></div>'+gpGrid(s,n=>B('step',n===s.path.at(-1)?'🧭':n===t.goal?'⚑':t.blocked.includes(n)?'▧':t.stops.includes(n)?'📦':s.path.includes(n)?'●':'',n,'class="gp-cell '+(t.blocked.includes(n)?'gp-blocked':s.path.includes(n)?'gp-path':'')+'" aria-label="Route square '+(n%6+1)+','+(Math.floor(n/6)+1)+'"'))+'<p class="gp-legend">Move one square at a time. Shaded squares are impassable. Each move = 1 km.</p>';
 if(k==='links')html='<div class="gp-network"><svg viewBox="0 0 600 260" aria-hidden="true">'+s.edges.map(([a,b])=>{const pa=s.deck.indexOf(a),pb=s.deck.indexOf(b),ax=100+(pa%3)*200,ay=43+Math.floor(pa/3)*(174/Math.max(1,Math.ceil(t.cards.length/3)-1)),bx=100+(pb%3)*200,by=43+Math.floor(pb/3)*(174/Math.max(1,Math.ceil(t.cards.length/3)-1));return '<path d="M'+ax+' '+ay+' L'+bx+' '+by+'" stroke="#ce8b35" stroke-width="5" marker-end="url(#gp-arrow-'+i+')"/>';}).join('')+'<defs><marker id="gp-arrow-'+i+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10z" fill="#ce8b35"/></marker></defs></svg><div class="gp-nodes">'+s.deck.map(n=>B('node',esc(t.cards[n].label),n,'aria-pressed="'+(s.selected===n)+'"')).join('')+'</div></div><p class="gp-legend">Tap a starting node, then its destination. Tap the same connection again to remove it. Arrows show direction.</p>';
 if(k==='timeline')html='<div class="gp-timeline">'+t.cards.map((_,n)=>B('slot',s.order[n]==null?'Stage '+(n+1):esc(t.cards[s.order[n]].label),n,'class="gp-slot" data-gp-drop="'+n+'"')).join('')+'</div><div class="gp-palette">'+s.deck.filter(n=>!s.order.includes(n)).map(n=>B('token',esc(t.cards[n].label),n,'class="gp-token" data-geo-drag="'+n+'" aria-pressed="'+(s.selected===n)+'"')).join('')+'</div>';
 if(k==='sort'||k==='compose')html='<div class="gp-bins">'+t.bins.map((b,n)=>'<section>'+B('bin',esc(b),n,'class="gp-bin-head" data-gp-drop="'+n+'"')+Object.entries(s.assigned).filter(([,bin])=>bin===n).map(([key])=>B('unassign',esc(t.cards[key].label),key,'class="gp-sorted"')).join('')+'</section>').join('')+'</div><div class="gp-palette">'+s.deck.filter(n=>s.assigned[n]===undefined).map(n=>B('token',esc(t.cards[n].label),n,'class="gp-token" data-geo-drag="'+n+'" aria-pressed="'+(s.selected===n)+'"')).join('')+'</div>';
 if(k==='redact')html='<article class="gp-report"><header>FIELD REPORT · EDITOR’S DESK</header>'+t.cards.map((c,n)=>B('redact',esc(c.label),n,'class="'+(s.removed.includes(n)?'gp-crossed':'')+'" aria-pressed="'+s.removed.includes(n)+'"')).join('')+'</article><p class="gp-legend">Strike out unsupported claims. Keep every statement supported by the source. Tap again to restore.</p>';
 if(k==='budget'){const chosen=t.items.filter((_,n)=>s.chosen.includes(n)),cost=chosen.reduce((v,p)=>v+p.cost,0),weight=chosen.reduce((v,p)=>v+p.weight,0);html='<div class="gp-inline"><b>🪙 '+cost+' / '+t.budget+'</b><b>🎒 '+weight+' / '+t.weight+' kg</b></div><p>Mission needs: '+t.needs.map(esc).join(' · ')+'</p><div class="gp-inventory">'+t.items.map((p,n)=>B('pack','<b>'+esc(p.label)+'</b><small>'+p.cost+' tokens · '+p.weight+' kg</small>',n,'aria-pressed="'+s.chosen.includes(n)+'"')).join('')+'</div>';}
 if(k==='allocate')html='<p class="gp-resource-count">'+(t.total-s.values.reduce((a,b)=>a+b,0))+' resource tokens left</p><div class="gp-allocations">'+t.users.map((u,n)=>'<section><strong>'+esc(u.label)+'</strong><small>Agreement: '+u.min+'–'+u.max+' tokens</small><div>'+B('allocation','−',n,'data-change="-1"')+'<b>'+s.values[n]+'</b>'+B('allocation','+',n,'data-change="1"')+'</div><div class="gp-resource-bar"><i style="width:'+Math.min(100,s.values[n]/u.max*100)+'%"></i></div></section>').join('')+'</div>';
 if(k==='ice')html='<div class="gp-ice-scene"><svg viewBox="0 0 600 150" aria-label="Model glacier with '+s.ice+' ice tokens"><path d="M0 150 140 5 275 150 390 30 600 150" fill="#a7d3e2"/><path d="M100 150 200 35 285 80 440 150" fill="#f3fcff"/><path class="gp-ice-tongue" d="M170 110Q300 70 '+(240+s.ice*7)+' 140H170z" fill="#5cbcd1"/><text x="20" y="40" font-size="30">'+s.ice+' ice tokens</text></svg></div><div class="gp-inline"><b>Year '+Math.min(s.year+1,t.weather.length)+' / '+t.weather.length+'</b><span>Melting this year: '+(t.weather[s.year]??'complete')+'</span><span>Snow budget left: '+s.snowLeft+'</span></div><div class="gp-inline">'+B('snow','−',-1)+'<b>Add '+s.snowNow+' snow</b>'+B('snow','+',1)+B('year','Run one year','', '',s.year===t.weather.length)+'</div><p>Target after '+t.weather.length+' years: '+t.target+' ice tokens. Melt forecast: '+t.weather.join(' → ')+'. '+s.years.map(v=>v.before+' + '+v.snow+' − '+v.melt+' = '+v.after).join(' · ')+'</p>';
 if(k==='river'){const landing=gpRiverLanding(t.sizes,s.energy);html='<div class="gp-river-scene"><svg viewBox="0 0 600 150" aria-label="River sediment model"><path d="M0 25Q180 120 300 75T600 105" fill="none" stroke="#8ad0dd" stroke-width="65"/>'+t.sizes.map((size,n)=>'<circle class="gp-grain" cx="'+(s.ran?90+landing[n]*210+n*10:25+n*28)+'" cy="'+(55+n%2*45)+'" r="'+(5+size*2)+'" fill="'+['#d78a50','#9e6c48','#c5b079','#9e7b91','#d9a756','#688b79'][n]+'" stroke="#fff" stroke-width="2">'+(s.ran&&gpMotion()?'<animate attributeName="cx" from="'+(25+n*28)+'" to="'+(90+landing[n]*210+n*10)+'" dur="1s" fill="freeze"/>':'')+'</circle>').join('')+'</svg></div><div class="gp-reaches">'+[0,1,2].map(n=>'<section><strong>Reach '+(n+1)+'</strong><div>'+B('energy','−',n,'data-change="-1"')+'<b>'+s.energy[n]+'</b>'+B('energy','+',n,'data-change="1"')+'</div></section>').join('')+'</div>'+B('flow','Release the sediment')+'<p class="gp-legend">A grain stops at the first reach whose energy is below its size. Grain sizes: '+t.sizes.join(', ')+'. Target reaches: '+t.targets.map(n=>n+1).join(', ')+'.</p>';}
 if(k==='profile'||k==='chart'){html='<div class="gp-plot" style="--columns:'+t.values.length+'">'+t.labels.map((label,n)=>'<div class="gp-column"><strong>'+s.values[n]+'</strong><div class="gp-column-track">'+Array.from({length:11},(_,v)=>B('plot','',n,'data-level="'+(10-v)+'" aria-label="'+esc(label)+', '+(10-v)+'" class="'+(s.values[n]>=10-v?'filled':'')+'"')).join('')+'</div><small>'+esc(label)+'</small></div>').join('')+'</div><p class="gp-legend">Tap a height in each column to '+(k==='profile'?'draw the landscape cross-section':'plot the station measurements')+'. Scale: 0–10 '+esc(t.unit||'units')+'.</p>';}
 if(k==='deduce')html='<div class="gp-clues">'+t.questions.map((v,n)=>B('ask',esc(v),n,'',s.asked.includes(n))).join('')+'</div><div class="gp-clue-notes">'+s.asked.map(n=>'<p>'+esc(t.suspects[t.target].facts[n])+'</p>').join('')+'</div><div class="gp-suspects">'+t.suspects.map((c,n)=>B('eliminate','<strong>'+esc(c.label)+'</strong><small>'+c.facts.map(esc).join(' · ')+'</small>',n,'aria-pressed="'+s.eliminated.includes(n)+'" class="'+(s.eliminated.includes(n)?'gp-crossed':'')+'"')).join('')+'</div><p class="gp-legend">Ask for clues, then cross out candidates that cannot match. Leave exactly one.</p>';
 if(k==='layers')html='<div class="gp-inline">'+t.layers.map((v,n)=>B('layer',esc(v.label),n,'aria-pressed="'+s.layers.includes(n)+'"')).join('')+'</div>'+gpGrid(s,n=>B('site',(s.site===n?'⚑ ':'')+t.layers.map((v,k)=>s.layers.includes(k)&&v.cells.includes(n)?'<span style="background:'+['#6aa8d6','#e1a365','#8cbb69','#b893ca'][k]+'">'+(k+1)+'</span>':'').join(''),n,'class="gp-cell" aria-label="Site '+String.fromCharCode(65+n%6)+(Math.floor(n/6)+1)+'"'))+'<p class="gp-legend">'+esc(t.rule)+'</p>';
 if(k==='survey')html='<p>Samples: '+s.samples.length+' / '+t.samples+' · collect evidence from all three zones.</p>'+gpGrid(s,n=>B('sample',s.samples.includes(n)?String(t.values[n]):['A','B','C'][t.zones[n]],n,'class="gp-cell gp-zone-'+t.zones[n]+' '+(s.samples.includes(n)?'gp-sampled':'')+'"'))+'<div class="gp-inline"><span>Report your sample total:</span>'+'<input class="gp-total" data-gp-total="'+i+'" type="number" min="0" max="160" aria-label="Sample total" value="'+s.prediction+'">'+'</div>';
 if(k==='sculpt')html='<div class="gp-inline">'+B('tool','Erode / remove','remove','aria-pressed="'+(s.tool==='remove')+'"')+B('tool','Deposit / build','add','aria-pressed="'+(s.tool==='add')+'"')+'</div><div class="gp-sculpture">'+s.rock.map((v,n)=>B('rock',String(v),n,'class="gp-rock gp-rock-'+v+'" aria-label="Landscape cell '+(n+1)+', height '+v+'"')).join('')+'</div><p class="gp-legend">'+esc(t.process)+'. Each tap changes the rock height by one unit. Match the supplied cross-section pattern.</p>';
 return html;
}
function gpPanel(i){const l=game.session.lanes[i],q=game.items[l.index],s=l.gp,k=q.geo.kind.slice(3),t=q.geo.task;let html='<div class="geo-panel-head"><strong>'+esc(l.name)+'</strong><span>'+l.score+' points · '+(l.index+1)+' / '+game.items.length+'</span></div><p class="geo-stage">'+esc(GP_TYPES[k])+'</p><h2>'+esc(q.prompt)+'</h2><details class="gp-brief"><summary>Mission brief & evidence</summary><p>'+esc(t.brief)+'</p><p>'+esc(q.geo.source)+'</p></details><div class="gp-task gp-'+k+'">'+gpTaskUI(i,q,l)+'</div><div class="gp-status" role="status">'+esc(s.notice||'Build your solution, then test it. You can revise your work.')+'</div><div class="gp-toolbar">'+gpButton(i,'undo','Undo')+gpButton(i,'reset','Reset work')+gpButton(i,'check','Test my work')+gpButton(i,'finish','Finish & review','', 'class="gp-review-finish"')+'</div>';return html;}
const gpOldPanel=geoPanelHTML;geoPanelHTML=function(i){const l=game.session.lanes[i];const q=game.items[l.index];if(gpIs(q)&&l.phase==='question')return gpPanel(i);if(gpIs(q)&&l.phase==='feedback')return '<div class="geo-panel-head"><strong>'+esc(l.name)+'</strong></div><p>Mission review</p><h2>'+esc(q.prompt)+'</h2><div class="geo-feedback '+(l.good?'good':'retry')+'"><strong>'+(l.good?'Mission complete':'Review and discuss')+'</strong><p>'+esc(q.geo.task.check)+'</p></div><details class="gp-brief"><summary>Show worked solution</summary><p>'+esc(q.answer)+'</p></details>'+geoButton(i,'next','Next mission');return gpOldPanel(i);};
function gpCheck(k,t,s){let good=false,detail='Check the brief and revise your work.';
 if(k==='map'||k==='build'){const n=t.targets.filter((p,i)=>{const v=s.placed[i];return v&&v.x===p.x&&v.y===p.y&&(k!=='build'||v.w===p.w&&v.h===p.h);}).length;good=n===t.targets.length;detail=n+' / '+t.targets.length+' features meet the location'+(k==='build'?' and scale':'')+' requirements.';}
 if(k==='route'){good=s.path.at(-1)===t.goal&&t.stops.every(n=>s.path.includes(n))&&s.path.length-1<=t.limit;detail='Reach the flag, visit every supply stop and stay within '+t.limit+' km.';}
 if(k==='links'){const set=new Set(s.edges.map(e=>e.join('-'))),right=t.edges.filter(e=>set.has(e.join('-'))).length;good=right===t.edges.length&&set.size===right;detail=right+' / '+t.edges.length+' required connections are present. Remove unsupported connections.';}
 if(k==='timeline'){const target=t.cards.map((c,i)=>({i,n:c.order})).sort((a,b)=>a.n-b.n).map(c=>c.i);good=target.every((n,i)=>s.order[i]===n);detail='Check which event or process must come before the next.';}
 if(k==='sort'||k==='compose'){const right=t.cards.filter((c,i)=>s.assigned[i]===c.bin).length;good=right===t.cards.length;detail=right+' / '+t.cards.length+' cards are in a supported category.';}
 if(k==='redact'){good=t.cards.every((c,i)=>s.removed.includes(i)===!c.keep);detail='Keep every supported statement, and remove every claim the source cannot support.';}
 if(k==='budget'){const all=t.items.filter((_,i)=>s.chosen.includes(i)),cost=all.reduce((n,p)=>n+p.cost,0),weight=all.reduce((n,p)=>n+p.weight,0),cover=all.reduce((n,p)=>n|p.cover,0);good=cost<=t.budget&&weight<=t.weight&&cover===(1<<t.needs.length)-1;detail='Plan test: '+cost+'/'+t.budget+' tokens, '+weight+'/'+t.weight+' kg. Needs met: '+t.needs.filter((_,i)=>cover&(1<<i)).join(', ')+'.';}
 if(k==='allocate'){good=s.values.reduce((a,b)=>a+b,0)<=t.total&&t.users.every((u,i)=>s.values[i]>=u.min&&s.values[i]<=u.max);detail='Respect the total supply and every stakeholder agreement. Several allocations may work.';}
 if(k==='ice'){good=s.year===t.weather.length&&s.ice===t.target;detail='Complete all years and reach '+t.target+' ice tokens. Plan with every year’s melt forecast.';}
 if(k==='river'){good=s.ran&&gpRiverLanding(t.sizes,s.energy).every((v,i)=>v===t.targets[i]);detail='Release the grains after adjusting energy. Compare the deposit reach of each grain with its target.';}
 if(k==='profile'||k==='chart'){good=s.values.every((n,i)=>n===t.values[i]);detail=s.values.filter((n,i)=>n===t.values[i]).length+' / '+t.values.length+' plotted values match the source.';}
 if(k==='deduce'){good=s.asked.length>=2&&s.eliminated.length===t.suspects.length-1&&!s.eliminated.includes(t.target);detail='Use at least two clues. Eliminate all contradictions and leave one supported candidate.';}
 if(k==='layers'){good=s.layers.length===t.layers.length&&t.valid.includes(s.site);detail='Inspect every layer and choose a site satisfying all the stated constraints.';}
 if(k==='survey'){good=s.samples.length===t.samples&&[0,1,2].every(z=>s.samples.filter(n=>t.zones[n]===z).length>=Math.floor(t.samples/3))&&s.prediction===s.samples.reduce((n,i)=>n+t.values[i],0);detail='Collect the required sample, represent all zones evenly, and report the total of your measurements.';}
 if(k==='sculpt'){good=s.rock.every((n,i)=>n===t.target[i]);detail=s.rock.filter((n,i)=>n===t.target[i]).length+' / 24 landscape cells match the required profile.';}
 return {good,detail};
}
function gpComplete(i,good){const l=game.session.lanes[i],penalty=good?Math.min(80,l.gp.tries*10):0;l.gp.notice='';geoScore(i,good);if(penalty){l.score-=penalty;game.score-=penalty;}l.history.at(-1).mission=game.items[l.index].geo.kind;l.history.at(-1).points=good?100-penalty:0;game.session.mode==='DUEL'?geoPaint(i):geoRender();}
const gpOldHandle=geoHandle;geoHandle=function(b){if(!b.dataset.modeAction?.startsWith('geo-play-'))return gpOldHandle(b);const i=Number(b.dataset.lane),l=game?.session?.lanes?.[i];if(!l||game.done||ui.view!=='player'||b.disabled||l.phase!=='question'||game.session.review||game.session.mode==='TEAM'&&game.session.active!==i)return;const q=game.items[l.index];if(!gpIs(q))return;const k=q.geo.kind.slice(3),t=q.geo.task,s=l.gp,a=b.dataset.modeAction.slice(9),n=Number(b.dataset.value),valid=(v,max)=>Number.isInteger(v)&&v>=0&&v<max;
 if(a==='check'){const {good,detail}=gpCheck(k,t,s);if(good){gpComplete(i,true);return;}s.tries++;s.notice=detail;geoPaint(i);return;}
 if(a==='finish'){gpComplete(i,false);return;}
 if(a==='reset'){const tries=s.tries,deck=s.deck;l.gp=gpNew(q);l.gp.deck=deck;l.gp.tries=tries;geoPaint(i);return;}
 if(a==='undo'){const history=s.undo||[],previous=history.pop();if(previous){const tries=s.tries;l.gp={...JSON.parse(previous),tries,undo:history};geoPaint(i);}return;}
 const before=JSON.stringify({...s,undo:undefined});let changed=true;
 if(a==='token'&&valid(n,t.targets?.length||t.cards?.length||0))s.selected=n;
 else if(a==='cell'&&['map','build'].includes(k)&&valid(n,30)&&valid(s.selected,t.targets.length)){const x=n%6,y=Math.floor(n/6);if(k==='build'&&(x+s.dimensions.w>6||y+s.dimensions.h>5)){s.notice='This building extends beyond the plan. Move it or reduce its size.';}else{s.placed[s.selected]={x,y,w:s.dimensions.w,h:s.dimensions.h};s.selected=null;s.notice='';}}
 else if(['width','height'].includes(a)&&k==='build'&&[-1,1].includes(n)){const key=a==='width'?'w':'h';s.dimensions[key]=Math.max(1,Math.min(key==='w'?6:5,s.dimensions[key]+n));}
 else if(a==='hide'&&k==='map')s.studied=true;
 else if(a==='step'&&k==='route'&&valid(n,30)){const last=s.path.at(-1);if(n===s.path.at(-2))s.path.pop();else if(gpNeighbours(last).includes(n)&&!t.blocked.includes(n)&&s.path.length-1<t.limit){s.path.push(n);s.notice='';}else s.notice='Move to an adjacent open square. Undo to change your route.';}
 else if(a==='node'&&k==='links'&&valid(n,t.cards.length)){if(s.selected===null)s.selected=n;else if(s.selected===n)s.selected=null;else{const at=s.edges.findIndex(e=>e[0]===s.selected&&e[1]===n);if(at>=0)s.edges.splice(at,1);else s.edges.push([s.selected,n]);s.selected=null;}}
 else if(a==='slot'&&k==='timeline'&&valid(n,t.cards.length)){if(s.selected===null){if(s.order[n]!=null){s.selected=s.order[n];delete s.order[n];}}else{const old=s.order.indexOf(s.selected);if(old>=0)delete s.order[old];s.order[n]=s.selected;s.selected=null;}}
 else if(a==='bin'&&['sort','compose'].includes(k)&&valid(n,t.bins.length)&&valid(s.selected,t.cards.length)){s.assigned[s.selected]=n;s.selected=null;}
 else if(a==='unassign'&&['sort','compose'].includes(k)&&valid(n,t.cards.length))delete s.assigned[n];
 else if(a==='redact'&&k==='redact'&&valid(n,t.cards.length))s.removed=s.removed.includes(n)?s.removed.filter(v=>v!==n):[...s.removed,n];
 else if(a==='pack'&&k==='budget'&&valid(n,t.items.length))s.chosen=s.chosen.includes(n)?s.chosen.filter(v=>v!==n):[...s.chosen,n];
 else if(a==='allocation'&&k==='allocate'&&valid(n,t.users.length)&&[-1,1].includes(Number(b.dataset.change)))s.values[n]=Math.max(0,Math.min(t.total,s.values[n]+Number(b.dataset.change)));
 else if(a==='snow'&&k==='ice'&&[-1,1].includes(n))s.snowNow=Math.max(0,Math.min(s.snowLeft,s.snowNow+n));
 else if(a==='year'&&k==='ice'&&s.year<t.weather.length){const melt=t.weather[s.year],after=Math.max(0,s.ice+s.snowNow-melt);s.years.push({before:s.ice,snow:s.snowNow,melt,after});s.ice=after;s.snowLeft-=s.snowNow;s.snowNow=0;s.year++;}
 else if(a==='energy'&&k==='river'&&valid(n,3)&&[-1,1].includes(Number(b.dataset.change))){s.energy[n]=Math.max(0,Math.min(5,s.energy[n]+Number(b.dataset.change)));s.ran=false;}
 else if(a==='flow'&&k==='river')s.ran=true;
 else if(a==='plot'&&['chart','profile'].includes(k)&&valid(n,t.values.length)&&valid(Number(b.dataset.level),11))s.values[n]=Number(b.dataset.level);
 else if(a==='ask'&&k==='deduce'&&valid(n,3)&&!s.asked.includes(n))s.asked.push(n);
 else if(a==='eliminate'&&k==='deduce'&&valid(n,t.suspects.length))s.eliminated=s.eliminated.includes(n)?s.eliminated.filter(v=>v!==n):[...s.eliminated,n];
 else if(a==='layer'&&k==='layers'&&valid(n,t.layers.length))s.layers=s.layers.includes(n)?s.layers.filter(v=>v!==n):[...s.layers,n];
 else if(a==='site'&&k==='layers'&&valid(n,30))s.site=n;
 else if(a==='sample'&&k==='survey'&&valid(n,30)){if(s.samples.includes(n))s.samples=s.samples.filter(v=>v!==n);else if(s.samples.length<t.samples)s.samples.push(n);else s.notice='Your sample is full. Remove a sample to choose another location.';}
 else if(a==='total'&&k==='survey'&&[-1,1].includes(n))s.prediction=Math.max(0,Math.min(160,s.prediction+n));
 else if(a==='tool'&&k==='sculpt'&&['remove','add'].includes(b.dataset.value))s.tool=b.dataset.value;
 else if(a==='rock'&&k==='sculpt'&&valid(n,24))s.rock[n]=Math.max(0,Math.min(3,s.rock[n]+(s.tool==='add'?1:-1)));
 else changed=false;
 if(changed){s.undo=[...(s.undo||[]),before].slice(-100);geoPaint(i);}
};
// Native pointer dragging supplements all tap controls; each gesture remains owned by its player's panel.
const gpPointers=new Map(),gpSuppressClick=new Map();
function gpFireTarget(el){if(el?.dataset.modeAction)geoHandle(el);}
document.addEventListener('pointerdown',e=>{const token=e.target.closest('[data-geo-drag]'),paint=e.target.closest('.gp-column-track,.gp-sculpture,.gp-route');if(!token&&!paint){const p=e.target.closest('[data-geo-panel]');if(p)gpSuppressClick.delete(Number(p.dataset.geoPanel));return;}const panel=e.target.closest('[data-geo-panel]');if(!panel)return;const lane=Number(panel.dataset.geoPanel);e.preventDefault();gpSuppressClick.set(lane,Date.now()+700);const first=token||e.target.closest('[data-mode-action]');gpPointers.set(e.pointerId,{lane,owner:game.session,drag:!!token,last:first?first.dataset.modeAction+':'+first.dataset.value+':'+first.dataset.level:null});gpFireTarget(token||e.target.closest('[data-mode-action]'));},{passive:false});
document.addEventListener('pointermove',e=>{const g=gpPointers.get(e.pointerId);if(!g||g.owner!==game?.session||g.drag)return;const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-mode-action]');if(!hit||Number(hit.dataset.lane)!==g.lane)return;const key=hit.dataset.modeAction+':'+hit.dataset.value+':'+hit.dataset.level;if(g.last!==key){g.last=key;gpFireTarget(hit);}e.preventDefault();},{passive:false});
document.addEventListener('pointerup',e=>{const g=gpPointers.get(e.pointerId);if(!g)return;if(g.owner!==game?.session){gpPointers.delete(e.pointerId);return;}if(g.drag){const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-gp-drop]');if(hit&&Number(hit.dataset.lane)===g.lane)gpFireTarget(hit);}gpPointers.delete(e.pointerId);gpSuppressClick.set(g.lane,Date.now()+700);});document.addEventListener('pointercancel',e=>gpPointers.delete(e.pointerId));
document.addEventListener('click',e=>{const b=e.target.closest('[data-mode-action^="geo-play-"]');if(b&&e.detail>0&&(gpSuppressClick.get(Number(b.dataset.lane))||0)>Date.now()){e.preventDefault();e.stopImmediatePropagation();}},true);

document.addEventListener('input',e=>{if(!e.target.matches('[data-gp-total]'))return;const lane=Number(e.target.dataset.gpTotal),l=game?.session?.lanes?.[lane];if(l?.phase==='question'&&l.gp)l.gp.prediction=Number(e.target.value);});
